"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 grounding package v0.6, sections 15.3 and 15.4: the extra read-outs, registered 2026-11-21 (commit 200677d)
before any dev run. Local only; train and dev; test and replication untouched (their scores come from the final run and
the grounding report, which read the files written here).

Read-outs (each a logistic regression per question S and R, fitted as the existing ones: holdout units of RO.SEED,
weight decay from RO.WDS by holdout log loss, refit on all, RO.train_logreg):
- "shuffled": step 2d's design (decision vectors at the two option positions + per-second ears, mean and max of each of
  the 8 seconds; 18,432 features) on step 2c's train forward, but the 8 seconds of every window in a random order (one
  permutation per train window from numpy seed 0, the mean and the max permuted together; when scoring, a permutation
  fixed by the window id; torch seed 0). It keeps every feature of 2d and loses only which second is which (G4c).
- "nat ears s{0-7}": step 2c ears' design (decision vectors + whole-window ears) on the natural-label train forward
  (data/p1v4/runs/grounding/control/feats_train_natural.npz, as the natural-label control), torch seeds 0-7 (G6 report).
- "nat sec8 s{0-7}": step 2d's design on the natural-label train forward, torch seeds 0-7 (G6a, G6a-S).
- "2c states s1", "2d s1": the 2c states read-out and the main read-out refitted with torch seed 1 (reported; the
  stored ones were fitted without a fixed start; the main system stays the stored 2d).
The ears are audio-only, so the natural-label read-outs take the same ears as the 2c / 2d fits (window ids asserted).
Thresholds: the plan's operating-point rule (p1v4_score.operating_point) on natural dev, from the final path's batch-8
dev features (data/p1v4/runs/final/dev/readouts/feats_natural.npz), as the main system's thresholds.
Commands:
  fit [name ...]   fit the read-outs (default: all) -> data/p1v4/runs/grounding/extra/<name>.npz, fit_log.json
  dev              natural dev thresholds and metrics -> results/main_v04/readout_extra_dev.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout_extra.py fit|dev
"""
import hashlib
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_2c as R2C  # noqa: E402
import p1v4_readout_2d as R2D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/grounding/extra"
RES = "results/main_v04/readout_extra_dev.json"
SEEDS = tuple(range(8))
NAT_EARS = tuple(f"nat ears s{s}" for s in SEEDS)
NAT_SEC8 = tuple(f"nat sec8 s{s}" for s in SEEDS)
NAMES = ("shuffled",) + NAT_EARS + NAT_SEC8 + ("2c states s1", "2d s1")
KIND = {"shuffled": "sec8", "2c states s1": "states", "2d s1": "sec8",
        **{n: "ears" for n in NAT_EARS}, **{n: "sec8" for n in NAT_SEC8}}


def path_of(name):
    return f"{OUT}/{name.replace(' ', '_')}.npz"


def id_perm(wid):
    """The fixed permutation of the 8 seconds used when scoring the shuffled read-out on a window."""
    return np.random.default_rng(int(hashlib.sha1(str(wid).encode("utf-8")).hexdigest()[:8], 16)).permutation(8)


def permute(sm, sx, perms):
    idx = np.asarray(perms)[:, :, None]
    return np.take_along_axis(sm, idx, 1), np.take_along_axis(sx, idx, 1)


# ------------------------------------------------------------------------------------------------ fit

def holdout(z):
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)                    # the same holdout units as every other read-out
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    return np.array([u in hold_units for u in units])


def fit_one(X, y, hold, label, log):
    """Standardise, choose the weight decay by holdout log loss, refit on all (as R2C.fit / R2D.fit)."""
    mu, sd = X.mean(0), X.std(0) + 1e-6
    X -= mu
    X /= sd
    Xh = X.astype(np.float16)
    del X
    best = None
    for wd in RO.WDS:
        lin = RO.train_logreg(Xh[~hold], y[~hold], wd)
        p = np.clip(RO.predict(lin, Xh[hold]), 1e-7, 1 - 1e-7)
        yy = y[hold]
        ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
        log[f"{label} wd {wd}"] = ll
        print(f"{label} wd {wd}: holdout log loss {ll:.4f}", flush=True)
        if best is None or ll < best[0]:
            best = (ll, wd)
    lin = RO.train_logreg(Xh, y, best[1])
    return {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
            "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1], "holdout_ll": best[0]}


def train_data():
    """The 2c train forward, the natural-label train forward and the per-second ears, aligned by window id."""
    c2 = dict(np.load(f"{R2C.OUT}/feats_train_2c.npz"))
    nat = dict(np.load(f"{R}/grounding/control/feats_train_natural.npz"))
    sec = np.load(f"{R2D.OUT}/sec8_train.npz")
    assert np.array_equal(c2["ids"], nat["ids"]) and np.array_equal(c2["ids"], sec["ids"]), "window order differs"
    nat["ears"] = c2["ears"]
    return c2, nat, sec["sec_mean"], sec["sec_max"], sec["ids"]


def fit(names=NAMES):
    import torch
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    c2, nat, sm_all, sx_all, ids = train_data()
    shuf = np.random.default_rng(0)
    perms = np.stack([shuf.permutation(8) for _ in range(len(ids))])
    logp = f"{OUT}/fit_log.json"
    log = json.load(open(logp)) if os.path.exists(logp) else {}
    for name in names:
        t0 = time.time()
        z = nat if name.startswith("nat ") else c2
        seed = int(name.rsplit(" s", 1)[1]) if name != "shuffled" else 0     # "shuffled": torch seed 0 (reproducible)
        hold = holdout(z)
        models = {}
        torch.manual_seed(seed)                                # once before the S and R fits (as the control starts)
        for q in ("S", "R"):
            m = np.where((z["q_task"] == q) & (z["q_gold"] >= 0))[0]
            wq = z["q_win"][m]
            if KIND[name] == "states":
                X = np.asarray(z["states"][m], dtype=np.float32)
            elif KIND[name] == "ears":
                X = np.concatenate([np.asarray(z["states"][m], dtype=np.float32),
                                    np.asarray(z["ears"][wq], dtype=np.float32)], 1)
            else:
                sm, sx = sm_all[wq], sx_all[wq]
                if name == "shuffled":
                    sm, sx = permute(sm, sx, perms[wq])
                X = R2D.design(z["states"][m], sm, sx)
            models[q] = fit_one(X, z["q_gold"][m], hold[m], f"{name} {q}", log)
        np.savez(path_of(name), **{f"{q}|{f}": v for q, d in models.items() for f, v in d.items()})
        json.dump(log, open(logp, "w"), indent=1)
        print(f"{name}: fitted in {time.time() - t0:.0f} s (wd S {models['S']['wd']}, R {models['R']['wd']})", flush=True)


def load(name):
    z = np.load(path_of(name))
    out = {}
    for k in z.files:
        q, f = k.split("|")
        out.setdefault(q, {})[f] = z[k]
    return out


# ------------------------------------------------------------------------------------------------ scores

def scores(name, z, ro=None):
    """{(unit, version, k): {"S": p, "R": p}} of an extra read-out on features z (states, ears, q_win, q_task, ids,
    and for the per-second kinds sec_mean / sec_max aligned with ids)."""
    ro = load(name) if ro is None else ro
    sc = {}
    wid = z["ids"][z["q_win"]]
    p = np.zeros(len(z["q_task"]))
    for q in ("S", "R"):
        m = np.where(z["q_task"] == q)[0]
        if not len(m):
            continue
        wq = z["q_win"][m]
        if KIND[name] == "states":
            X = np.asarray(z["states"][m], dtype=np.float32)
        elif KIND[name] == "ears":
            X = np.concatenate([np.asarray(z["states"][m], dtype=np.float32),
                                np.asarray(z["ears"][wq], dtype=np.float32)], 1)
        else:
            sm = np.asarray(z["sec_mean"][wq], dtype=np.float32)
            sx = np.asarray(z["sec_max"][wq], dtype=np.float32)
            if name == "shuffled":
                sm, sx = permute(sm, sx, np.stack([id_perm(w) for w in wid[m]]))
            X = R2D.design(z["states"][m], sm, sx)
        r = ro[q]
        lg = ((X - r["mu"]) / r["sd"]) @ r["w"] + float(r["b"])
        p[m] = 1 / (1 + np.exp(-lg))
    for w, q, x in zip(z["q_win"], z["q_task"], p):
        i = z["ids"][w].split("|")
        sc.setdefault((i[0], i[1], int(i[2])), {})[str(q)] = float(x)
    return sc


def score_all(z, names=NAMES):
    return {n: scores(n, z) for n in names if os.path.exists(path_of(n))}


def dev():
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    z = dict(np.load(f"{R}/final/dev/readouts/feats_natural.npz"))
    out = {"features": f"{R}/final/dev/readouts/feats_natural.npz", "readouts": {}}
    for name, sc in score_all(z).items():
        op = S.operating_point(rows, sc)
        m = S.metrics(S.unit_table(rows, S.decide(sc, op["th_s"], op["th_r"]), groups))
        out["readouts"][name] = {"th_s": float(op["th_s"]), "th_r": float(op["th_r"]), "five_part": m["primary"],
                                 "must_listen": m["audio"], "floors_met": op["floors_met"],
                                 "lowest_floor": op["lowest_floor"], "file": path_of(name)}
        print(f"{name}: th S {op['th_s']:.4g} R {op['th_r']:.4g}; natural dev five-part {m['primary']:.4f}, "
              f"must-listen {m['audio']:.3f}", flush=True)
    json.dump(out, open(RES, "w"), indent=1)
    print("wrote", RES)


if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "fit":
        fit(tuple(" ".join(a[1:]).split(",")) if len(a) > 1 else NAMES)
    elif a and a[0] == "dev":
        dev()
    else:
        raise SystemExit(__doc__)
